def quote(body,marker):
 assert marker in body,marker
 return next(s.strip()+'。' for s in body.split('。') if marker in s)
def source(key):
 path,q,meaning=S[key];txt=(P/path).read_text();assert q in txt,(key,q)
 return dict(path=path,quote=q,line=txt[:txt.index(q)].count('\n')+1,meaning=meaning)
def filepath(raw):
 add=raw.startswith('+');raw=raw.lstrip('+')
 return ('src/'+raw if raw.startswith(('app/','shared/')) else 'src/features/'+raw),('add' if add else 'modify')
